package com.desecratedtree.quill.cache;
import com.desecratedtree.quill.sprite.*; import com.desecratedtree.quill.texture.*; import com.desecratedtree.quill.texture.synth.*; import java.awt.image.*; import java.nio.file.*; import org.junit.jupiter.api.*;
class TexturePatternDiagnosticTest {
 @Test void scan(){Assumptions.assumeTrue(Files.isDirectory(Paths.get("data/cache"))); CacheManager.init("data/cache"); int shown=0; for(int id=0;id<2000;id++){byte[] d=CacheManager.getTextureData(id); if(d==null)continue; try{TextureProgram p=new TextureProgram(d); if(p.spriteFileIds().length==0)continue; BufferedImage out=TextureLoader.previewTexture(id); BufferedImage src=SpriteArchiveCodec.decode(CacheManager.getSpriteData(p.spriteFileIds()[0])).sprites.get(0).toBufferedImage(); int[] bad=new int[4]; for(int mode=0;mode<4;mode++)for(int y=0;y<out.getHeight();y++)for(int x=0;x<out.getWidth();x++){int sx=src.getWidth()*x/out.getWidth(),sy=src.getHeight()*y/out.getHeight();if(mode==1)sx=src.getWidth()-1-sx;if(mode==2)sy=src.getHeight()-1-sy;if(mode==3){int z=sx;sx=sy;sy=z;} int a=out.getRGB(x,y),b=src.getRGB(Math.min(src.getWidth()-1,sx),Math.min(src.getHeight()-1,sy));int la=((a>>16&255)+(a>>8&255)+(a&255))/3,lb=((b>>16&255)+(b>>8&255)+(b&255))/3;if(Math.abs(la-lb)>40)bad[mode]++;} int best=0;for(int i=1;i<4;i++)if(bad[i]<bad[best])best=i; int total=out.getWidth()*out.getHeight(); if(bad[best]>total/4 && shown++<30)System.err.println("id="+id+" sprite="+p.spriteFileIds()[0]+" layers="+p.layers.length+" out="+out.getWidth()+"x"+out.getHeight()+" bad="+java.util.Arrays.toString(bad)+" best="+best); }catch(Exception ignored){}}
 }
}
